/* USART1_RX (DMA half transfer / transfer complete) */
void DMA1_Channel5_IRQHandler(void)
{
  /* USER CODE BEGIN DMA1_Channel5_IRQn 0 */
  const uint32_t c0 = DWT->CYCCNT;
  ISR_GPIO_Port->BSRR = ISR_Pin;
  rx_irqs++;
  /* USER CODE END DMA1_Channel5_IRQn 0 */
  HAL_DMA_IRQHandler(&hdma_usart1_rx);
  /* USER CODE BEGIN DMA1_Channel5_IRQn 1 */
  rx_cycles += DWT->CYCCNT - c0;
  ISR_GPIO_Port->BRR = ISR_Pin;
  /* USER CODE END DMA1_Channel5_IRQn 1 */
}

/* USART2_TX (the "sensor" side) */
void DMA1_Channel7_IRQHandler(void)
{
  HAL_DMA_IRQHandler(&hdma_usart2_tx);
}

void USART1_IRQHandler(void)
{
  /* USER CODE BEGIN USART1_IRQn 0 */
  const uint32_t c0 = DWT->CYCCNT;
  ISR_GPIO_Port->BSRR = ISR_Pin;
  rx_irqs++;
  /* HAL v1.1.9 notifies an IDLE event only while the DMA counter is between
     0 and the ring size: when a message ends exactly where the ring wraps
     (TC already reported, counter reloaded to RX_RING_SIZE) the IDLE flag is
     cleared silently. Catch that case before HAL_UART_IRQHandler clears it. */
  if (rx_mode == RX_DMA_CIRCULAR && (USART1->SR & USART_SR_IDLE) != 0U && (USART1->CR1 & USART_CR1_IDLEIE) != 0U &&
      (USART1->CR3 & USART_CR3_DMAR) != 0U && __HAL_DMA_GET_COUNTER(&hdma_usart1_rx) == RX_RING_SIZE)
  {
    App_IdleAtWrap();
  }
  /* USER CODE END USART1_IRQn 0 */
  HAL_UART_IRQHandler(&huart1);
  /* USER CODE BEGIN USART1_IRQn 1 */
  rx_cycles += DWT->CYCCNT - c0;
  ISR_GPIO_Port->BRR = ISR_Pin;
  /* USER CODE END USART1_IRQn 1 */
}

void USART2_IRQHandler(void)
{
  HAL_UART_IRQHandler(&huart2);
}
